def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    day = day_context['day']
    supply = day_context['supply']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive = []
    prev_bids = []
    urgent_prev_bids = []
    rich_prev_bids = []

    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)
            prev = opp.get('previous_trace', {})
            bid = prev.get('bid') if prev else None
            if bid is not None:
                prev_bids.append(float(bid))
                if opp.get('no_water_days', 0) >= 1 or opp.get('hp', 10) <= 4:
                    urgent_prev_bids.append(float(bid))
                if opp.get('budget', 0) >= budget * 0.8:
                    rich_prev_bids.append(float(bid))

    if not alive:
        return float(min(budget, 8.0))

    high_supply = supply >= 21
    low_supply = supply <= 17

    max_prev = max(prev_bids) if prev_bids else 0.0
    urgent_max = max(urgent_prev_bids) if urgent_prev_bids else max_prev
    rich_max = max(rich_prev_bids) if rich_prev_bids else max_prev

    if hp <= 2 or no_water >= 2:
        bid = max(62.0, urgent_max + 2.5, rich_max + 1.5)
    elif hp <= 4 or no_water >= 1:
        bid = max(48.0, urgent_max + 1.5)
        if low_supply:
            bid = max(bid, rich_max + 1.0)
    else:
        if high_supply:
            bid = max(18.0, min(36.0, max_prev * 0.45 + 4.0))
        elif low_supply:
            bid = max(30.0, min(58.0, rich_max + 1.0))
        else:
            bid = max(24.0, min(46.0, max_prev * 0.6 + 3.0))

    if day >= 8 and hp >= 6 and no_water == 0:
        bid *= 0.9

    reserve = 0.0
    if hp >= 5 and no_water == 0:
        reserve = DAILY_SALARY * 1.2
    elif hp >= 3:
        reserve = DAILY_SALARY * 0.6

    cap = max(0.0, budget - reserve)
    if hp <= 3 or no_water >= 1:
        cap = budget

    bid = min(bid, cap if cap > 0 else budget)
    bid = min(bid, budget)
    bid = max(0.0, bid)
    return float(round(bid, 2))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context.get('supply', 0.0))
    day = int(day_context.get('day', 0))

    my_hp = float(my_status.get('hp', 0.0))
    my_budget = float(my_status.get('budget', 0.0))
    my_no_water_days = int(my_status.get('no_water_days', 0))

    alive_opps = []
    for oid, o in opponents_status.items():
        if o.get('alive', False):
            alive_opps.append(o)

    if my_budget <= 0:
        return 0.0

    if not alive_opps:
        return min(my_budget, DAILY_SALARY * 0.4)

    # Yesterday reaction: use only previous_trace immediate info
    yesterday_bids = []
    yesterday_supplies = []
    for o in alive_opps:
        prev = o.get('previous_trace', {}) or {}
        if prev.get('bid') is not None:
            try:
                yesterday_bids.append(float(prev.get('bid')))
            except Exception:
                pass
        if prev.get('supply') is not None:
            try:
                yesterday_supplies.append(float(prev.get('supply')))
            except Exception:
                pass

    highest_prev_bid = max(yesterday_bids) if yesterday_bids else 0.0
    avg_prev_bid = (sum(yesterday_bids) / len(yesterday_bids)) if yesterday_bids else 0.0

    # Estimate how many water units supply allows; bid scales to compete for at least 1 unit.
    # Convert to an integer count safely.
    supply_units = int(supply / float(WATER_REQ)) if WATER_REQ > 0 else 0
    if supply_units < 1:
        supply_units = 1

    # Base strategy: undercut typical bids to avoid burning budget, but still bid enough.
    # Typical yesterday bids were ~104-118; target slightly below average.
    base_target = max(DAILY_SALARY * 0.45, avg_prev_bid * 0.92)

    # Escalation rules
    # If my hp is low or I'm already accumulating no-water days, bid harder.
    must_win = (my_hp <= 2.5) or (my_no_water_days >= 2)

    # If someone bid extremely high yesterday, they likely were desperate; we can either free-ride
    # (bid slightly less) unless we must win.
    extreme_pressure = highest_prev_bid >= DAILY_SALARY * 0.85

    if must_win:
        # Spend to secure water.
        target = max(base_target, DAILY_SALARY * 0.75)
        if extreme_pressure:
            target = max(target, highest_prev_bid * 0.97)
    else:
        if extreme_pressure:
            # Avoid matching the top; undercut to win if others overpay.
            target = min(highest_prev_bid * 0.9, base_target)
        else:
            # Normal: bid around base target.
            target = base_target

    # Cap by what we can afford and by a day-based conservative scaling.
    # Early days slightly more conservative to preserve budget over 10 days.
    day_factor = 1.0
    if day <= 3:
        day_factor = 0.95
    elif day >= 8:
        day_factor = 1.05

    target *= day_factor

    # Final clamp
    target = max(0.0, target)
    if target > my_budget:
        target = my_budget

    # Ensure we bid at least a small amount if we need water soon
    if must_win and target < DAILY_SALARY * 0.55:
        target = min(my_budget, DAILY_SALARY * 0.7)

    return float(target)

